int spfy_fe_baked_dict_lookup(const char *word_lc, size_t word_len,
                              const uint16_t **out_phons,
                              const uint8_t  **out_stress,
                              size_t *out_n)
{
    int lo = 0, hi = SPFY_FE_BAKED_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        const char *s = &SP_BUF[ENT[mid].sp_off];
        size_t slen = strlen(s);
        size_t cmplen = slen < word_len ? slen : word_len;
        int c = memcmp(word_lc, s, cmplen);
        if (c == 0) {
            if (word_len == slen) {
                *out_phons = &POOL[ENT[mid].pool_off];
                if (out_stress)
                    *out_stress = &POOL_STRESS[ENT[mid].pool_off];
                *out_n = ENT[mid].pool_len;
                return 1;
            }
            c = (word_len < slen) ? -1 : 1;
        }
        if (c < 0) hi = mid - 1; else lo = mid + 1;
    }
    return 0;
}
